 function commit(change){const before=state;state=structuredClone(state);change(state);try{localStorage.setItem(stateKey,JSON.stringify(state));return true;}catch{state=before;toast('Çalışma verileri kaydedilemedi. Depolama alanını kontrol edip yedek al.');return false;}}
 function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('zaman-study-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onsuccess=()=>resolve(r.result);r.onerror=()=>{dbPromise=null;reject(r.error);};});return dbPromise;}
 async function store(key,value,remove=false){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('settings','readwrite');if(remove)tx.objectStore('settings').delete(key);else tx.objectStore('settings').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
 async function read(key){const database=await db();return new Promise((resolve,reject)=>{const r=database.transaction('settings').objectStore('settings').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
