 async function chooseBackground(file){if(!file)return;if(file.size>12*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('En fazla 12 MB boyutunda JPG, PNG veya WebP seç.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();if(image.naturalWidth*image.naturalHeight>60000000)throw Error('Daha küçük boyutlu bir görsel seç.');const ratio=Math.min(1,1920/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*ratio);canvas.height=Math.round(image.naturalHeight*ratio);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));if(!blob||blob.size>2*1024*1024)throw Error('Görsel hazırlanamadı. Daha sade bir görsel seç.');await store('background',blob);commit(s=>s.settings.background=true);await loadBackground();toast('Arka plan kaydedildi.');}finally{URL.revokeObjectURL(url);}}
 window.exportStudyBackup=async()=>{const blob=await read('background');return {...structuredClone(state),timer:null,backgroundData:blob?'data:image/jpeg;base64,'+await blobBase64(blob):''};};
 window.validateStudyBackup=value=>{if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Geçersiz çalışma yedeği');if(value.checklists!==undefined&&(!Array.isArray(value.checklists)||value.checklists.length>100||!value.checklists.every(SeiriChecklistModel.valid)))throw Error('Geçersiz checklist yedeği');if(value.backgroundData&&(!/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(value.backgroundData)||value.backgroundData.length>2800000))throw Error('Geçersiz arka plan');return true;};
 window.importStudyBackup=async value=>{window.validateStudyBackup(value);const incoming=M.normalize(value);incoming.templates.forEach(t=>t.html=sanitizeRich(t.html));if(value.backgroundData){const raw=atob(value.backgroundData.split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));if(bytes[0]!==255||bytes[1]!==216||bytes[2]!==255)throw Error('Geçersiz arka plan');await store('background',new Blob([bytes],{type:'image/jpeg'}));}const merge=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,x])).values()];commit(s=>{s.sessions=merge(s.sessions,incoming.sessions).sort((a,b)=>a.endedAt-b.endedAt).slice(-2000);s.tasks=merge(s.tasks,incoming.tasks).slice(-500);s.completions=merge(s.completions,incoming.completions).sort((a,b)=>a.at-b.at).slice(-2000);s.templates=merge(s.templates,incoming.templates).slice(-30);s.checklists=merge(s.checklists||[],incoming.checklists||[]).slice(-100);s.settings=incoming.settings;s.focusCycles=Math.max(s.focusCycles,incoming.focusCycles);});await loadBackground();if(page==='journal')renderStudy();};
 function recordCompletion(kind,item,done){commit(s=>{if(kind==='task'){const task=s.tasks.find(x=>x.id===item.id);if(task)task.completedAt=done?Date.now():0;}s.completions.push({id:uid(),entryId:item.id,title:item.title,kind,action:done?'completed':'reopened',at:Date.now()});s.completions=s.completions.slice(-2000);});}
